let windowSim = {};
const W = 100, H = 100;

function reset(balls) {
    balls = [
        { x: 50, y: 85, vx: 0.1, vy: 0 },
        { x: 35, y: 25, vx: 2, vy: 0 },
        { x: 75, y: 65, vx: -1, vy: 0 },
        { x: 95, y: 45, vx: 0.5, vy: 0 },
        { x: 65, y: 35, vx: -0.5, vy: 0 },
        { x: 95, y: 65, vx: 1, vy: 0 }
    ];
}

function draw() {
    const ctx = document.getElementById('canvas').getContext('2d');
    ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);
    for (let i = 0; i < 6; i++) {
        const ball = windowSim.balls[i];
        // center position relative to table boundaries
        const cx = ball.x + ball.vx * W/2;
        const cy = ball.y + ball.vy * H/2; // vy is zero for all balls in reset, so after step they move.
        ctx.beginPath();
        ctx.arc(cx + W/2 - ball.y*W/4, cy + H/2 - ball.x*W/4, 3, 0, Math.PI);
        ctx.fill();
    }
}

function step(dt) {
    windowSim.dt = dt;
    const ballsArray = windowSim.balls;
    for (let i = 0; i < 6; i++) {
        const vx = ballsArray[i].vx;
        const vy = ballsArray[i].vy;
        ballsArray[i].cx += vx * dt; // x-direction
        ballsArray[i].cy += vy * dt; // y-direction
    }
}

