                   y > -radius && y < radius + radius * 0.5;
        }

        // Check if point is a pocket
        function isPocket(x, y) {
            for (const pocket of getPockets()) {
                if (Math.abs(pocket.x - x) <= radius * 0.5 &&
                    Math.abs(pocket.y - y) <= radius * 0.5) {
                    return true;
                }
            }
            return false;
        }

        // Collision detection function
        function distance(x1, y1) { return Math.sqrt(x1**2 + y1**2); }

