                balls[cueBall.cueIndex] = cueBall;
            }
        }

        // Step function
        function step(dt) {
            windowSize.x -= dt * 0.005; // adjust for 500px width (approx)
            windowSize.y += dt * 0.025; // adjust for 400px height (approx)

            // Reset positions to current state (not necessary if we update immediately, but let's do it)
